// Fan out: one item per PDF attachment on each email.
const out = [];
$input.all().forEach((item, idx) => {
  const j = item.json;
  const from = j.from?.value?.[0]?.address || j.from?.text || '';
  for (const [key, file] of Object.entries(item.binary || {})) {
    const name = (file.fileName || key).toLowerCase();
    if (!(file.mimeType || '').includes('pdf') && !name.endsWith('.pdf')) continue;
    out.push({
      json: {
        email_id: j.id,
        email_subject: j.subject || '',
        email_from: from,
        email_date: j.date || '',
        file_name: file.fileName || key,
      },
      binary: { data: file },
      pairedItem: { item: idx },
    });
  }
});
return out;

