// Clean the AI output into a flat, spreadsheet-safe row and flag anything a human should look at.
const src = $('Split PDF Attachments').item.json;
const o = $json.output || {};
const num = (v) => {
  if (typeof v === 'number') return Math.round(v * 100) / 100;
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : 0;
};
const isoDate = (v) => {
  if (!v) return '';
  const d = new Date(v);
  return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10);
};
const clean = (s) => String(s ?? '').trim();

let minConfidence = 0.85;
try { minConfidence = Number($('Config').first().json.minConfidence ?? 0.85); } catch (e) { /* free version has no Config node */ }

const subtotal = num(o.subtotal), tax = num(o.tax), total = num(o.total);
const lineItems = Array.isArray(o.line_items) ? o.line_items : [];
const confidence = Math.max(0, Math.min(1, Number(o.confidence) || 0));

const notes = [];
if (!clean(o.invoice_number)) notes.push('Missing invoice number');
if (!total) notes.push('Missing total');
if (subtotal && Math.abs(subtotal + tax - total) > 0.02) notes.push(`Math mismatch: ${subtotal} + ${tax} != ${total}`);
if (confidence < minConfidence) notes.push(`Low AI confidence (${confidence})`);

return {
  json: {
    processed_at: new Date().toISOString(),
    email_id: src.email_id,
    email_from: src.email_from,
    email_subject: src.email_subject,
    file_name: src.file_name,
    vendor_name: clean(o.vendor_name),
    vendor_email: clean(o.vendor_email),
    invoice_number: clean(o.invoice_number),
    po_number: clean(o.po_number),
    invoice_date: isoDate(o.invoice_date),
    due_date: isoDate(o.due_date),
    currency: (clean(o.currency) || 'USD').toUpperCase().slice(0, 3),
    subtotal,
    tax,
    total,
    line_count: lineItems.length,
    line_items_json: JSON.stringify(lineItems),
    confidence,
    status: notes.length ? 'needs_review' : 'extracted',
    review_notes: notes.join('; '),
  },
};
